```yaml
- ansible.builtin.include_vars: {file: stuff.yaml, name: stuff}
- ansible.builtin.include_vars: "{{ lookup('ansible.builtin.first_found', params) }}"
  vars:
    params:
      files: ['{{ansible_distribution}}.yaml', '{{ansible_os_family}}.yaml', default.yaml]
      paths: [vars]
- ansible.builtin.include_vars: {dir: vars/all, extensions: [json, jsn]}
- ansible.builtin.include_vars: {dir: vars/services, depth: 1}
- ansible.builtin.include_vars: {dir: vars, ignore_files: [bastion.yaml], extensions: [yaml]}
```
